import Foundation
import Vapor
import GraphQL

// MARK: - GraphQL Query Builder
struct QueryContext {
    let userRole: String
    let tenantId: String
    let requestId: String
}

class GraphQLQueryResolver {
    private let schemaDefinition: String
    private let allowedIntrospectionDepth: Int = 3

    init() {
        self.schemaDefinition = """
        type Query {
            user(id: ID!): User
            users(filter: UserFilter): [User]
            tenant(id: ID!): Tenant
        }
        type User {
            id: ID!
            name: String
            email: String
            role: String
            tenantId: String
        }
        input UserFilter {
            name: String
            role: String
            tenantId: String
        }
        type Tenant {
            id: ID!
            name: String
            users: [User]
        }
        """
    }

    func buildFilteredQuery(baseQuery: String, context: QueryContext) -> String {
        // Apply tenant isolation at the query level.
        // The tenantId originates from a client-controlled header, so it must be
        // validated and escaped before being placed into the query string to
        // prevent GraphQL injection through the tenant identifier.
        let safeTenantId = GraphQLQueryResolver.sanitizeTenantId(context.tenantId)
        let tenantClause = "tenantId: \"\(safeTenantId)\""
        return injectTenantFilter(query: baseQuery, filter: tenantClause)
    }

    /// Validates and escapes a tenant identifier so it cannot break out of the
    /// GraphQL string literal context. Only a conservative character set is
    /// allowed; anything else is rejected/stripped.
    static func sanitizeTenantId(_ tenantId: String) -> String {
        let allowed = CharacterSet(charactersIn: "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_")
        let filtered = String(tenantId.unicodeScalars.filter { allowed.contains($0) })
        // Fall back to a safe default if the header contained no valid characters.
        return filtered.isEmpty ? "default" : filtered
    }

    private func injectTenantFilter(query: String, filter: String) -> String {
        // Find the filter argument position and inject tenant constraint
        guard let filterRange = query.range(of: "filter:") else {
            // No filter block - append tenant filter as argument
            return appendTenantArgument(query: query, filter: filter)
        }

        // Insert tenant constraint into existing filter
        let insertionPoint = query.index(after: filterRange.upperBound)
        var modified = query
        // Find the opening brace of the filter object
        if let braceIdx = modified[insertionPoint...].firstIndex(of: "{") {
            let afterBrace = modified.index(after: braceIdx)
            modified.insert(contentsOf: " \(filter), ", at: afterBrace)
        }
        return modified
    }

    private func appendTenantArgument(query: String, filter: String) -> String {
        // For queries without filter, add tenant constraint
        guard let parenIdx = query.firstIndex(of: "(") else {
            return query
        }
        var modified = query
        let afterParen = modified.index(after: parenIdx)
        modified.insert(contentsOf: "filter: { \(filter) }, ", at: afterParen)
        return modified
    }
}

// MARK: - Request Sanitizer
class QuerySanitizer {
    private static let dangerousPatterns: [String] = [
        "__schema", "__type", "mutation", "subscription"
    ]

    static func sanitize(input: String) -> String {
        var cleaned = input
        // Remove comments that could hide injection
        cleaned = cleaned.replacingOccurrences(
            of: "#[^\\n]*",
            with: "",
            options: .regularExpression
        )
        return cleaned
    }

    static func validateQueryDepth(_ query: String, maxDepth: Int = 5) -> Bool {
        var depth = 0
        var maxFound = 0
        for char in query {
            if char == "{" { depth += 1; maxFound = max(maxFound, depth) }
            if char == "}" { depth -= 1 }
        }
        return maxFound <= maxDepth
    }

    static func containsDangerousPatterns(_ query: String) -> Bool {
        let normalized = query.lowercased()
        return dangerousPatterns.contains { normalized.contains($0) }
    }
}

// MARK: - Variable Interpolation Engine
class VariableInterpolator {
    /// Resolves GraphQL variables by passing them as a separate variables object
    /// to the upstream engine - never interpolates into the query string
    func resolveVariables(query: String, variables: [String: Any]) -> (String, [String: Any]) {
        // Return query unchanged; variables passed separately to upstream
        return (query, variables)
    }

    private func stringRepresentation(of value: Any) -> String {
        switch value {
        case let str as String:
            // Escape quotes for GraphQL string context
            return str.replacingOccurrences(of: "\\\"", with: "\\\\\\\"")
        case let num as Int:
            return String(num)
        case let bool as Bool:
            return bool ? "true" : "false"
        case let arr as [Any]:
            let items = arr.map { stringRepresentation(of: $0) }
            return "[\(items.joined(separator: ", "))]" 
        default:
            return "null"
        }
    }
}

// MARK: - API Route Handler
func configureRoutes(_ app: Application) throws {
    let resolver = GraphQLQueryResolver()
    let interpolator = VariableInterpolator()

    app.post("graphql") { req -> EventLoopFuture<Response> in
        struct GraphQLRequest: Content {
            let query: String
            let variables: [String: AnyCodable]?
            let operationName: String?
        }

        let gqlRequest = try req.content.decode(GraphQLRequest.self)

        // Step 1: Sanitize the raw query
        let sanitized = QuerySanitizer.sanitize(input: gqlRequest.query)

        // Step 2: Validate query structure
        guard QuerySanitizer.validateQueryDepth(sanitized) else {
            throw Abort(.badRequest, reason: "Query too deeply nested")
        }
        guard !QuerySanitizer.containsDangerousPatterns(sanitized) else {
            throw Abort(.forbidden, reason: "Introspection queries not allowed")
        }

        // Step 3: Resolve variables - kept separate from query
        let vars = gqlRequest.variables?.mapValues { $0.value } ?? [:]
        let (queryWithoutVars, separateVars) = interpolator.resolveVariables(query: sanitized, variables: vars)

        // Step 4: Apply tenant isolation.
        // Header-derived values are validated/escaped inside buildFilteredQuery.
        let context = QueryContext(
            userRole: req.headers.first(name: "X-User-Role") ?? "viewer",
            tenantId: req.headers.first(name: "X-Tenant-ID") ?? "default",
            requestId: UUID().uuidString
        )
        let finalQuery = resolver.buildFilteredQuery(baseQuery: queryWithoutVars, context: context)

        // Step 5: Execute against upstream GraphQL service
        return executeUpstream(query: finalQuery, variables: separateVars, on: req)
    }
}

func executeUpstream(query: String, variables: [String: Any], on req: Request) -> EventLoopFuture<Response> {
    let upstreamURL = Environment.get("GRAPHQL_UPSTREAM") ?? "http://graphql-engine:8080/v1/graphql"
    return req.client.post(URI(string: upstreamURL)) { upstream in
        try upstream.content.encode(["query": query, "variables": variables])
    }.map { clientResponse in
        let response = Response(status: clientResponse.status)
        response.body = clientResponse.body.map { Response.Body(buffer: $0) } ?? .empty
        response.headers.contentType = .json
        return response
    }
}

// MARK: - AnyCodable helper
struct AnyCodable: Codable {
    let value: Any
    init(_ value: Any) { self.value = value }
    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let str = try? container.decode(String.self) { value = str }
        else if let int = try? container.decode(Int.self) { value = int }
        else if let bool = try? container.decode(Bool.self) { value = bool }
        else if let arr = try? container.decode([AnyCodable].self) { value = arr.map { $0.value } }
        else if let dict = try? container.decode([String: AnyCodable].self) { value = dict.mapValues { $0.value } }
        else { value = "null" }
    }
    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(String(describing: value))
    }
}
